/**
 * Runs the production build: static files from dist/client, everything else
 * through the Start server entry's fetch handler. `PORT` defaults to 4341.
 */
import { fileURLToPath } from "node:url";
import { join, normalize } from "node:path";
// @ts-expect-error: generated by `vite build`
import server from "./dist/server/server.js";

const client = fileURLToPath(new URL("./dist/client/", import.meta.url));
const port = Number(process.env.PORT ?? 4341);

Bun.serve({
  port,
  async fetch(request) {
    const path = decodeURIComponent(new URL(request.url).pathname);
    const file = normalize(join(client, path));
    if (file.startsWith(client) && path !== "/") {
      const asset = Bun.file(file);
      if (await asset.exists()) return new Response(asset);
    }
    return server.fetch(request);
  },
});

console.log(`TanStack Start fixture on http://localhost:${port}`);
